                    len(documents)
                )

            with tracer.start_as_current_span(
                "rag.generation"
            ):

                answer = generate(
                    question,
                    documents
                )

            with tracer.start_as_current_span(
                "rag.output_validation"
            ) as span:

                valid = validate(
                    answer,
                    documents,
                    principal
                )

                span.set_attribute(
                    "rag.output.valid",
                    bool(valid)
                )

            if not valid:

                root.set_attribute(
                    "rag.outcome",
                    "blocked"
                )

                return {
                    "status": "blocked",
                    "answer": None
                }

            root.set_attribute(
                "rag.outcome",
                "success"
            )

            return {
                "status": "success",
                "answer": answer
            }

        except Exception as exc:

            root.set_attribute(
                "error.type",
                type(exc).__name__
            )

            root.set_status(
                Status(StatusCode.ERROR)
            )

            raise

